import os

def top_lnk(root, n):
    if n <= 0:
        return []
    results = []
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            if name.lower().endswith(".lnk"):
                path = os.path.join(dirpath, name)
                try:
                    size = os.path.getsize(path)
                except OSError:
                    continue
                results.append((size, path))
    results.sort(key=lambda item: (-item[0], item[1]))
    return results[:n]

用
os.walk
 递归遍历，跳过读取失败的条目，按大小降序（同大小按路径升序保证稳定）取前 n 个。

def dedup(items):
    seen_hashable = set()
    seen_unhashable = []
    result = []
    for item in items:
        try:
            hash(item)
        except TypeError:
            if any(item == seen for seen in seen_unhashable):
                continue
            seen_unhashable.append(item)
        else:
            if item in seen_hashable:
                continue
            seen_hashable.add(item)
        result.append(item)
    return result

可哈希元素用 set 判重（O(1)），不可哈希元素（dict、list 等）按
==
 线性比较，保证顺序与通用性。
